function experienceListFacts(it){const r=it?.raw||{};const time=it?.time||r.time||r.duration||'Flexible',cost=it?.cost||r.cost||'Check locally',booking=it?.booking||r.booking||'Usually flexible';return `<div class="tc1ExpMeta"><span>${esc(time)}</span><span>${esc(cost)}</span><span>${esc(booking)}</span></div>`}
